package com.videomind.module.agent.service;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.fasterxml.jackson.databind.*;import com.videomind.agentclient.AgentClientProperties;import com.videomind.common.exception.BizException;import com.videomind.module.agent.entity.MindAgentBinding;import com.videomind.module.agent.mapper.MindAgentBindingMapper;import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;import java.util.concurrent.TimeUnit;import org.redisson.api.*;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class MindAgentBindingService{private static final String SCOPES="openid profile knowledge:read knowledge:write chat:read chat:write tasks:read";private final AgentClientProperties p;private final MindAgentBindingMapper mapper;private final TokenCipher cipher;private final StringRedisTemplate redis;private final RedissonClient redisson;private final ObjectMapper json;private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(10)).build();public MindAgentBindingService(AgentClientProperties p,MindAgentBindingMapper m,TokenCipher c,StringRedisTemplate r,RedissonClient redisson,ObjectMapper j){this.p=p;mapper=m;cipher=c;redis=r;this.redisson=redisson;json=j;}
 public Map<String,Object>status(Long user){MindAgentBinding b=find(user);return b==null?Map.of("bound",false):Map.of("bound",true,"subject",b.getMindagentSubject(),"username",String.valueOf(b.getMindagentUsername()),"status",b.getStatus());}
 public String authorizationUrl(Long user){String state=random(32),verifier=random(48),challenge=pkce(verifier);redis.opsForValue().set("mindagent:oauth:state:"+state,user+"|"+verifier,Duration.ofMinutes(10));return p.getFrontendUrl()+"/oauth/authorize?response_type=code&client_id="+enc(p.getOauthClientId())+"&redirect_uri="+enc(p.getOauthRedirectUri())+"&scope="+enc(SCOPES)+"&state="+enc(state)+"&code_challenge="+enc(challenge)+"&code_challenge_method=S256";}
 @Transactional public void callback(Long currentUser,String code,String state){String saved=redis.opsForValue().getAndDelete("mindagent:oauth:state:"+state);if(saved==null)throw new BizException(400,"绑定状态已过期，请重新发起");String[]parts=saved.split("\\|",2);Long user=Long.valueOf(parts[0]);if(!user.equals(currentUser))throw new BizException(403,"绑定请求不属于当前用户");JsonNode token=token(Map.of("grant_type","authorization_code","client_id",p.getOauthClientId(),"client_secret",p.getOauthClientSecret(),"code",code,"redirect_uri",p.getOauthRedirectUri(),"code_verifier",parts[1]));String access=token.path("access_token").asText(),refresh=token.path("refresh_token").asText();JsonNode info=get("/v1/userinfo",access);String subject=info.path("sub").asText();MindAgentBinding other=mapper.selectOne(new LambdaQueryWrapper<MindAgentBinding>().eq(MindAgentBinding::getMindagentSubject,subject).ne(MindAgentBinding::getUserId,user));if(other!=null){revoke(refresh);throw new BizException(409,"该 MindAgent 账号已绑定其他 VideoMind 账号");}MindAgentBinding b=find(user);if(b==null){b=new MindAgentBinding();b.setUserId(user);b.setCreatedAt(LocalDateTime.now());}else revoke(cipher.decrypt(b.getRefreshTokenCipher()));b.setMindagentSubject(subject);b.setMindagentUsername(info.path("preferred_username").asText());b.setAccessTokenCipher(cipher.encrypt(access));b.setRefreshTokenCipher(cipher.encrypt(refresh));b.setScopes(token.path("scope").asText(SCOPES));b.setAccessExpiresAt(LocalDateTime.now().plusSeconds(token.path("expires_in").asLong(900)));b.setStatus("ACTIVE");b.setUpdatedAt(LocalDateTime.now());if(b.getId()==null)mapper.insert(b);else mapper.updateById(b);}
 public String accessToken(Long user){MindAgentBinding b=find(user);if(b==null)throw new BizException(401,"MINDAGENT_BINDING_REQUIRED");if(b.getAccessExpiresAt().isAfter(LocalDateTime.now().plusMinutes(1)))return cipher.decrypt(b.getAccessTokenCipher());RLock lock=redisson.getLock("mindagent:token:refresh:"+user);try{if(!lock.tryLock(5,30,TimeUnit.SECONDS))throw new BizException(503,"MindAgent 令牌刷新繁忙");b=find(user);if(b.getAccessExpiresAt().isAfter(LocalDateTime.now().plusMinutes(1)))return cipher.decrypt(b.getAccessTokenCipher());JsonNode token=token(Map.of("grant_type","refresh_token","client_id",p.getOauthClientId(),"client_secret",p.getOauthClientSecret(),"refresh_token",cipher.decrypt(b.getRefreshTokenCipher())));b.setAccessTokenCipher(cipher.encrypt(token.path("access_token").asText()));b.setRefreshTokenCipher(cipher.encrypt(token.path("refresh_token").asText()));b.setAccessExpiresAt(LocalDateTime.now().plusSeconds(token.path("expires_in").asLong(900)));mapper.updateById(b);return cipher.decrypt(b.getAccessTokenCipher());}catch(InterruptedException e){Thread.currentThread().interrupt();throw new BizException(503,"令牌刷新被中断");}finally{if(lock.isHeldByCurrentThread())lock.unlock();}}
 @Transactional public void unlink(Long user){MindAgentBinding b=find(user);if(b==null)return;revoke(cipher.decrypt(b.getRefreshTokenCipher()));mapper.deleteById(b.getId());}
 private MindAgentBinding find(Long user){return mapper.selectOne(new LambdaQueryWrapper<MindAgentBinding>().eq(MindAgentBinding::getUserId,user).eq(MindAgentBinding::getStatus,"ACTIVE"));}private JsonNode token(Map<String,String>form){try{String body=form.entrySet().stream().map(e->enc(e.getKey())+"="+enc(e.getValue())).collect(java.util.stream.Collectors.joining("&"));HttpRequest req=HttpRequest.newBuilder(URI.create(base()+"/oauth2/token")).header("Content-Type","application/x-www-form-urlencoded").POST(HttpRequest.BodyPublishers.ofString(body)).build();HttpResponse<String>res=http.send(req,HttpResponse.BodyHandlers.ofString());if(res.statusCode()/100!=2)throw new BizException(502,"MindAgent 授权失败："+res.body());return json.readTree(res.body());}catch(BizException e){throw e;}catch(Exception e){throw new BizException(502,"MindAgent 授权请求失败："+e.getMessage());}}private JsonNode get(String path,String access){try{HttpResponse<String>r=http.send(HttpRequest.newBuilder(URI.create(base()+path)).header("Authorization","Bearer "+access).GET().build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()/100!=2)throw new BizException(502,"MindAgent 用户信息读取失败");return json.readTree(r.body());}catch(BizException e){throw e;}catch(Exception e){throw new BizException(502,e.getMessage());}}private void revoke(String token){try{String body="token="+enc(token);http.send(HttpRequest.newBuilder(URI.create(base()+"/oauth2/revoke")).header("Content-Type","application/x-www-form-urlencoded").POST(HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.discarding());}catch(Exception ignored){}}private String base(){return p.getBaseUrl().replaceAll("/+$","");}private String random(int n){byte[]b=new byte[n];new SecureRandom().nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}private String pkce(String v){try{return Base64.getUrlEncoder().withoutPadding().encodeToString(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.US_ASCII)));}catch(Exception e){throw new IllegalStateException(e);}}private String enc(String v){return URLEncoder.encode(v,StandardCharsets.UTF_8);}}
